insert into public.reference_photos (categoria, tipo_peca, pose, data_comemorativa, nome_referencia, prompt_mestre, perfis_sugeridos, aspecto, ordem, status) values ('evergreen', 'Brinco', 'Still Branco (Packshot)', NULL, 'brinco_still-branco-packshot', 'Utilize exclusivamente a joia da fotografia anexada como referência do produto. Antes de gerar, identifique exatamente quantas peças e quantas unidades de cada peça existem na fotografia anexada (por exemplo, um par de brincos conta como duas unidades) e reproduza exatamente essa mesma quantidade na imagem final — nunca invente, duplique, repita, clone, remova ou complete o conjunto adicionando peças, pingentes, pedras ou componentes que não estejam fisicamente presentes na foto original. Se a foto anexada não contiver determinado tipo de peça (por exemplo, não houver anel), essa peça não deve aparecer na imagem final sob nenhuma hipótese. Preserve com fidelidade absoluta: formato, proporções, espessura, acabamento, brilho, textura, cor do metal, pedras (corte, tamanho e posição), cravação, fechos e elos, e todos os demais detalhes originais da peça. Não redesenhe, reinterprete, estilize, complete, corrija ou invente nenhuma característica da joia — reproduza exatamente o que existe na imagem original. Não utilize a foto anexada como referência de cenário, iluminação, enquadramento ou composição — ela serve apenas para identificar a peça, sua quantidade exata e seus detalhes exatos; remova completamente quaisquer objetos, mãos ou fundos presentes na foto original. Atenção especial à espessura de correntes, elos e fios: é um erro comum de IA generativa deixar correntes finas e delicadas mais grossas, mais vistosas ou mais robustas do que a peça real. A corrente gerada precisa ter exatamente a mesma espessura, o mesmo diâmetro de elo e a mesma delicadeza da foto original — NUNCA mais grossa, mais larga ou mais chamativa do que o original, mesmo que isso a deixe visualmente mais sutil ou difícil de perceber na imagem gerada.

Composição: Deixe um brinco apoiado em pé, em ângulo de aproximadamente 45° em relação à câmera, e o outro brinco deitado naturalmente sobre a superfície ao lado. Caso a peça tenha tarraxa, mantenha uma tarraxa presa em cada brinco — nunca deixe a tarraxa solta ou separada da peça.

Fotografia still de produto (packshot) profissional para e-commerce. Fundo branco puro (RGB 255,255,255), infinito, sem linha de horizonte, sem gradientes, sem textura e sem qualquer elemento decorativo. Iluminação de estúdio: uma fonte de luz principal ampla e difusa, uma luz de preenchimento suave do lado oposto para controlar sombras, e uma luz de contorno sutil para destacar a silhueta. Reflexos no metal limpos, contínuos e fisicamente corretos, sem brilhos estourados. Sombra de contato única, suave e difusa, com leve gradiente natural logo abaixo da peça. Lente equivalente entre 85mm e 105mm, foco perfeitamente nítido em toda a peça, sem distorção de perspectiva.

Qualidade: altíssima resolução, nitidez máxima na joia, excelente alcance dinâmico, texturas naturais, reflexos fisicamente corretos, cores absolutamente fiéis, acabamento fotográfico profissional. Eliminar completamente aparência de renderização 3D, ruído digital, granulado, halos ou qualquer aspecto artificial típico de imagem gerada por IA. A peça não deve parecer flutuando, tombada ou fora de escala — preserve rigorosamente suas proporções e comportamento físico real. Antes de finalizar, confirme item por item: a quantidade de peças geradas é idêntica à da foto original (nem a mais, nem a menos); nenhuma peça, pingente ou pedra foi inventado, duplicado ou removido; todos os detalhes de acabamento batem com o original. Formato final da imagem: 3:4 (vertical).', NULL, '3:4 (vertical)', 1, 'a_gerar') on conflict (nome_referencia) do nothing;
insert into public.reference_photos (categoria, tipo_peca, pose, data_comemorativa, nome_referencia, prompt_mestre, perfis_sugeridos, aspecto, ordem, status) values ('evergreen', 'Brinco', 'Still Humanizado', NULL, 'brinco_still-humanizado', 'Utilize exclusivamente a joia da fotografia anexada como referência do produto. Antes de gerar, identifique exatamente quantas peças e quantas unidades de cada peça existem na fotografia anexada (por exemplo, um par de brincos conta como duas unidades) e reproduza exatamente essa mesma quantidade na imagem final — nunca invente, duplique, repita, clone, remova ou complete o conjunto adicionando peças, pingentes, pedras ou componentes que não estejam fisicamente presentes na foto original. Se a foto anexada não contiver determinado tipo de peça (por exemplo, não houver anel), essa peça não deve aparecer na imagem final sob nenhuma hipótese. Preserve com fidelidade absoluta: formato, proporções, espessura, acabamento, brilho, textura, cor do metal, pedras (corte, tamanho e posição), cravação, fechos e elos, e todos os demais detalhes originais da peça. Não redesenhe, reinterprete, estilize, complete, corrija ou invente nenhuma característica da joia — reproduza exatamente o que existe na imagem original. Não utilize a foto anexada como referência de cenário, iluminação, enquadramento ou composição — ela serve apenas para identificar a peça, sua quantidade exata e seus detalhes exatos; remova completamente quaisquer objetos, mãos ou fundos presentes na foto original. Atenção especial à espessura de correntes, elos e fios: é um erro comum de IA generativa deixar correntes finas e delicadas mais grossas, mais vistosas ou mais robustas do que a peça real. A corrente gerada precisa ter exatamente a mesma espessura, o mesmo diâmetro de elo e a mesma delicadeza da foto original — NUNCA mais grossa, mais larga ou mais chamativa do que o original, mesmo que isso a deixe visualmente mais sutil ou difícil de perceber na imagem gerada.

Composição: mostrar apenas a orelha e a lateral do rosto (apenas esses elementos — não mostrar o restante do rosto), evidenciando a peça de forma natural.

Fotografia editorial extremamente realista para catálogo premium de joias, produzida como uma campanha de joalheria de luxo. Enquadramento fechado, mostrando apenas a orelha e a lateral do rosto (apenas esses elementos — não mostrar o restante do rosto) — nunca mostrar rosto, olhos, boca, nariz, cabelo ou outras partes do corpo além das indicadas. A pele deve ter aparência extremamente natural, saudável e uniforme, com tom: [PERFIL]. Criar uma única faixa de sombra diagonal, contínua e bem definida, inclinada aproximadamente 45°, atravessando a composição como luz entrando por uma janela — a sombra nunca deve cruzar ou escurecer a peça, que deve permanecer completamente iluminada e em destaque. Vestuário minimalista em tecido acetinado ou seda fosca, em tom off-white, extremamente discreto para não competir com a joia. Lente equivalente entre 85mm e 105mm, profundidade de campo rasa — a pele pode ficar levemente desfocada, mas a peça deve permanecer perfeitamente nítida. Fundo neutro (cinza quente muito suave ou bege acinzentado), sem textura, objetos ou elementos decorativos. Não adicionar outras joias, acessórios ou maquiagem chamativa.

Qualidade: altíssima resolução, nitidez máxima na joia, excelente alcance dinâmico, texturas naturais, reflexos fisicamente corretos, cores absolutamente fiéis, acabamento fotográfico profissional. Eliminar completamente aparência de renderização 3D, ruído digital, granulado, halos ou qualquer aspecto artificial típico de imagem gerada por IA. A peça não deve parecer flutuando, tombada ou fora de escala — preserve rigorosamente suas proporções e comportamento físico real. Garanta anatomia perfeita da orelha e do lóbulo — sem deformações, sem uma segunda orelha ou rosto fantasma aparecendo no enquadramento. Antes de finalizar, confirme item por item: a quantidade de peças geradas é idêntica à da foto original (nem a mais, nem a menos); nenhuma peça, pingente ou pedra foi inventado, duplicado ou removido; todos os detalhes de acabamento batem com o original. Formato final da imagem: 3:4 (vertical).', 'Mulher jovem (18-25), pele clara | Mulher adulta (30-45), pele morena | Mulher adulta (30-45), pele negra | Mulher idosa (60+), pele clara', '3:4 (vertical)', 2, 'a_gerar') on conflict (nome_referencia) do nothing;
